.frequency-display{font-family:'JetBrains Mono',ui-monospace,monospace;font-size:3.75rem;font-weight:700;color:var(--amber);line-height:1;}
.visualizer-container{height:150px;border:1px solid var(--border);border-radius:4px;overflow:hidden;position:relative;background:var(--panel-2);}
#visualizer{width:100%;height:100%;display:block;}

.waveform-btn.active{background:var(--amber-dim);color:var(--amber);border-color:var(--amber);}
.btn-success{background:var(--success);color:#fff;}

input[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:4px;border-radius:99px;background:var(--border);outline:none;cursor:pointer;margin:.4rem 0;}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:16px;height:16px;border-radius:50%;background:var(--amber);border:2px solid var(--bg);box-shadow:0 0 0 1px var(--amber);cursor:pointer;}
input[type=range]::-moz-range-thumb{width:16px;height:16px;border-radius:50%;background:var(--amber);border:2px solid var(--bg);box-shadow:0 0 0 1px var(--amber);cursor:pointer;}
input[type=range]::-moz-range-track{height:4px;border-radius:99px;background:var(--border);}
input[type=range]:disabled{opacity:.4;cursor:not-allowed;}
